parameters.jsCode:
const criteria = $('Normalizar criterios').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.employee_id !== undefined && r.employee_id !== null);

const DAY = 24 * 60 * 60 * 1000;
const today = new Date();
today.setHours(0, 0, 0, 0);

// Fecha limite de incorporacion segun la peticion
let target = null;
if (criteria.availability === 'immediate') {
  target = new Date(today.getTime() + 14 * DAY); // "lo antes posible" = disponible en los proximos 14 dias
} else if (criteria.availability && /^\d{4}-\d{2}-\d{2}$/.test(criteria.availability)) {
  target = new Date(criteria.availability + 'T00:00:00');
}

function toDate(v) {
  if (!v) return null;
  const d = new Date(v);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}
function fmt(d) {
  if (!d) return null;
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + dd;
}

const evaluated = [];
for (const r of rows) {
  const status = String(r.availability_status || '').trim().toLowerCase();
  const busy = status === 'busy';
  const date = toDate(r.availability_date);
  let available;
  if (busy) {
    // Una persona "busy" solo cuenta si tiene fecha de disponibilidad dentro del plazo
    available = date !== null && (target === null || date <= target);
  } else {
    available = date === null || target === null || date <= target;
  }
  if (!available) continue;
  const effective = date && date > today ? date : today;
  evaluated.push({ r, busy, effective });
}

// Orden: disponibilidad (antes primero, no-busy primero) y despues anos de experiencia
evaluated.sort((a, b) => {
  if (a.effective.getTime() !== b.effective.getTime()) return a.effective - b.effective;
  if (a.busy !== b.busy) return a.busy ? 1 : -1;
  return Number(b.r.years_experience || 0) - Number(a.r.years_experience || 0);
});

const matches = evaluated.slice(0, 5).map(({ r, effective }) => ({
  employee_id: r.employee_id,
  name: r.name,
  role: r.role,
  skills: Array.isArray(r.skills) ? r.skills : [],
  years_experience: r.years_experience,
  availability_status: r.availability_status,
  availability_date: fmt(toDate(r.availability_date)),
  available_from: fmt(effective),
  location: r.location,
}));

if (matches.length === 0) {
  return [{ json: { matches: [], reason: 'No se ha encontrado ningún perfil que cumpla todos los requisitos.', criteria } }];
}
return [{ json: { matches, total_found: matches.length, requested: criteria.number_of_profiles, criteria } }];

